1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/mpyop.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This code has been pulled from the cpuops.v file so as to
8	//		encapsulate the multiply component--the one component that
9	//	(can't be) formally verified well, and so must be abstracted away.
10	//	This separation was done to support potential future abstraction.
11	//
12	//
13	// Creator:	Dan Gisselquist, Ph.D.
14	//		Gisselquist Technology, LLC
15	//
16	////////////////////////////////////////////////////////////////////////////////
17	// }}}
18	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
19	// {{{
20	// This program is free software (firmware): you can redistribute it and/or
21	// modify it under the terms of the GNU General Public License as published
22	// by the Free Software Foundation, either version 3 of the License, or (at
23	// your option) any later version.
24	//
25	// This program is distributed in the hope that it will be useful, but WITHOUT
26	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
27	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
28	// for more details.
29	//
30	// You should have received a copy of the GNU General Public License along
31	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
32	// target there if the PDF file isn't present.)  If not, see
33	// <http://www.gnu.org/licenses/> for a copy.
34	// }}}
35	// License:	GPL, v3, as defined and found on www.gnu.org,
36	// {{{
37	//		http://www.gnu.org/licenses/gpl.html
38	//
39	////////////////////////////////////////////////////////////////////////////////
40	//
41	`default_nettype	none
42	// }}}
43	module	mpyop #(
44			// {{{
45			// The following parameter selects which multiply algorithm we
46			// use.  Timing performance is strictly dependent upon it.
47			//	OPY_MPY
48			//	------
49			//	   0	No multiply
50			//	   1	Single op multiply, same timing as an ADD
51			//	   2	Two clock multiply
52			//	   3	Three clock multiply, standard Xlnx DSP timing
53			//	   4	Three clock multiply, Xilinx Spartan DSP timing
54			//	(Anything else)	-- low logic slow multiply
55			//	  36	Required setting for the TB to work on the low
56			//		logic slow multiply
57			parameter	OPT_MPY = 1,
58			parameter [0:0]	OPT_LOWPOWER  = 1'b0
59			// }}}
60		) (
61			// {{{
62			input	wire		i_clk, i_reset, i_stb,
63			//
64			// Three types of multiply operations.
65			// 2'b00: 32x32 multiply, returning the low order 32 bits
66			// 2'b10: 32x32 unsigned multiply, returning upper 32 bits
67			// 2'b11: 32x32   signed multiply, returning upper 32 bits
68			input	wire	[1:0]	i_op,
69			input	wire	[31:0]	i_a, i_b,
70			output	wire		o_valid, // True if the result is valid
71			output	wire		o_busy,	//
72			output	wire	[63:0]	o_result, // multiply result
73			output	wire		o_hi	// Return the high half of mpy
74			// }}}
75		);
76	
77	
78		// A 4-way multiplexer can be done in one 6-LUT.
79		// A 16-way multiplexer can therefore be done in 4x 6-LUT's with
80		//	the Xilinx multiplexer fabric that follows.
81		// Given that we wish to apply this multiplexer approach to 33-bits,
82		// this will cost a minimum of 132 6-LUTs.
83	
84	// i_stb instead of this_is_a_multiply_op
85	// o_result
86	// o_busy
87	// o_done
88		generate
89		if (OPT_MPY == 0)
90		begin : MPYNONE // No multiply support.
91			// {{{
92			assign	o_result   = 64'h00;
93			assign	o_busy     = 1'b0;
94			assign	o_valid    = i_stb;
95			assign	o_hi = 1'b0; // Not needed
96	
97	`ifdef	VERILATOR
98			// verilator coverage_off
99			// verilator lint_off UNUSED
100			wire	mpy_unused;
101			assign	mpy_unused = &{ 1'b0, i_clk, i_reset, i_stb, i_op, i_a, i_b };
102			// verilator lint_on  UNUSED
103			// verilator coverage_on
104	`endif
105			// }}}
106		end else begin : IMPY
107		if (OPT_MPY == 1)
108		begin : MPY1CK // Our single clock option (no extra clocks)
109			// {{{
110			wire	signed	[63:0]	w_mpy_a_input, w_mpy_b_input;
111	
112			assign	w_mpy_a_input = {{(32){(i_a[31])&(i_op[0])}},i_a[31:0]};
113			assign	w_mpy_b_input = {{(32){(i_b[31])&(i_op[0])}},i_b[31:0]};
114	
115			assign	o_result = (OPT_LOWPOWER && !i_stb) ? 0 : (w_mpy_a_input * w_mpy_b_input);
116	
117			assign	o_busy  = 1'b0;
118			assign	o_valid = i_stb;
119			assign	o_hi = i_op[1];
120	
121	`ifdef	VERILATOR
122			// verilator coverage_off
123			// verilator lint_off UNUSED
124			wire	mpy_unused;
125			assign	mpy_unused = &{ 1'b0, i_clk, i_reset, i_stb, i_op[1] };
126			// verilator lint_on  UNUSED
127			// verilator coverage_on
128	`endif
129			// }}}
130		end else begin: MPN1
131		if (OPT_MPY == 2)
132		begin : MPY2CK // Our two clock option (ALU must pause for 1 clock)
133			// {{{
134	
135			// Declarations
136			// {{{
137			reg	signed	[63:0]	r_mpy_a_input, r_mpy_b_input;
138			reg			mpypipe, r_hi;
139			// }}}
140	
141			// r_mpy_?_input: Register the inputs
142			// {{{
143			always @(posedge i_clk)
144			if (!OPT_LOWPOWER || i_stb)
145			begin
146				r_mpy_a_input <={{(32){(i_a[31])&(i_op[0])}},i_a[31:0]};
147				r_mpy_b_input <={{(32){(i_b[31])&(i_op[0])}},i_b[31:0]};
148			end else begin
149				r_mpy_a_input <= 0;
150				r_mpy_b_input <= 0;
151			end
152			// }}}
153	
154			assign	o_result = r_mpy_a_input * r_mpy_b_input;
155			assign	o_busy  = 1'b0;
156	
157			// mpypipe
158			// {{{
159			initial	mpypipe = 1'b0;
160			always @(posedge i_clk)
161			if (i_reset)
162				mpypipe <= 1'b0;
163			else
164				mpypipe <= (i_stb);
165			// }}}
166	
167			assign	o_valid = mpypipe; // this_is_a_multiply_op;
168	
169			// o_hi
170			// {{{
171			always @(posedge i_clk)
172			if (i_stb)
173				r_hi  <= i_op[1];
174	
175			assign	o_hi = r_hi;
176			// }}}
177			// }}}
178		end else begin : MPN2
179		if (OPT_MPY == 3)
180		begin : MPY3CK // Our three clock option (ALU pauses for 2 clocks)
181			// {{{
182	
183			// Declarations
184			// {{{
185			reg	signed	[63:0]	r_smpy_result;
186			reg		[63:0]	r_umpy_result;
187			reg	signed	[31:0]	r_mpy_a_input, r_mpy_b_input;
188			reg		[1:0]	mpypipe;
189			reg		[1:0]	r_sgn;
190			reg			r_hi;
191			// }}}
192	
193			// mpypipe (FSM state)
194			// {{{
195			initial	mpypipe = 2'b0;
196			always @(posedge i_clk)
197			if (i_reset)
198				mpypipe <= 2'b0;
199			else
200				mpypipe <= { mpypipe[0], i_stb };
201			// }}}
202	
203			// First clock : register r_mpy_?_input, r_sgn
204			// {{{
205			always @(posedge i_clk)
206				r_sgn <= { r_sgn[0],
207					(i_op[0] && (!OPT_LOWPOWER || i_stb)) };
208	
209			always @(posedge i_clk)
210			if (!OPT_LOWPOWER || i_stb)
211			begin
212				r_mpy_a_input <= i_a[31:0];
213				r_mpy_b_input <= i_b[31:0];
214			end else begin
215				r_mpy_a_input <= 0;
216				r_mpy_b_input <= 0;
217			end
218			// }}}
219	
220			// Second clock : perform the multiply
221			// {{{
222	`ifdef	VERILATOR
223			// Veri1ator only implementation
224			// {{{
225			wire	signed	[63:0]	s_mpy_a_input, s_mpy_b_input;
226			wire		[63:0]	u_mpy_a_input, u_mpy_b_input;
227	
228			assign	s_mpy_a_input = {{(32){r_mpy_a_input[31]}},r_mpy_a_input};
229			assign	s_mpy_b_input = {{(32){r_mpy_b_input[31]}},r_mpy_b_input};
230			assign	u_mpy_a_input = {32'h00,r_mpy_a_input};
231			assign	u_mpy_b_input = {32'h00,r_mpy_b_input};
232			always @(posedge i_clk)
233			if (!OPT_LOWPOWER || mpypipe[0])
234				r_smpy_result <= s_mpy_a_input * s_mpy_b_input;
235			always @(posedge i_clk)
236			if (!OPT_LOWPOWER || mpypipe[0])
237				r_umpy_result <= u_mpy_a_input * u_mpy_b_input;
238			// }}}
239	`else
240			// Synthesis implementation
241			// {{{
242			wire		[31:0]	u_mpy_a_input, u_mpy_b_input;
243	
244			assign	u_mpy_a_input = r_mpy_a_input;
245			assign	u_mpy_b_input = r_mpy_b_input;
246	
247			always @(posedge i_clk)
248			if (!OPT_LOWPOWER || mpypipe[0])
249				r_smpy_result <= r_mpy_a_input * r_mpy_b_input;
250			always @(posedge i_clk)
251			if (!OPT_LOWPOWER || mpypipe[0])
252				r_umpy_result <= u_mpy_a_input * u_mpy_b_input;
253			// }}}
254	`endif
255	
256			always @(posedge i_clk)
257			if (i_stb)
258				r_hi  <= i_op[1];
259	
260			assign	o_hi    = r_hi;
261			assign	o_busy  = mpypipe[0];
262			assign	o_result = (r_sgn[1])?r_smpy_result:r_umpy_result;
263			assign	o_valid = mpypipe[1];
264			// }}}
265	
266			// Results are then available and registered on the third clock
267			// }}}
268		end else begin : MPN3
269		if (OPT_MPY == 4)
270		begin : MPY4CK // The four clock option, polynomial multiplication
271			// {{{
272			// Declarations
273			// {{{
274			reg	[63:0]	r_mpy_result;
275			reg	[31:0]	r_mpy_a_input, r_mpy_b_input;
276			reg		r_mpy_signed, r_hi;
277			reg	[2:0]	mpypipe;
278			reg	[31:0]	pp_f, pp_l; // F and L from FOIL
279			reg	[32:0]	pp_oi; // The O and I from FOIL
280			reg	[32:0]	pp_s;
281			// }}}
282	
283			// First clock, latch in the inputs : mpypipe, r_mpy_?_input
284			// {{{
285			initial	mpypipe = 3'b0;
286			always @(posedge i_clk)
287			begin
288				// mpypipe indicates we have a multiply in the
289				// pipeline.  In this case, the multiply
290				// pipeline is a two stage pipeline, so we need
291				// two bits in the pipe.
292				if (i_reset)
293					mpypipe <= 3'h0;
294				else begin
295					mpypipe[0] <= i_stb;
296					mpypipe[1] <= mpypipe[0];
297					mpypipe[2] <= mpypipe[1];
298				end
299	
300				if (i_op[0]) // i.e. if signed multiply
301				begin
302					r_mpy_a_input <= {(~i_a[31]),i_a[30:0]};
303					r_mpy_b_input <= {(~i_b[31]),i_b[30:0]};
304				end else begin
305					r_mpy_a_input <= i_a[31:0];
306					r_mpy_b_input <= i_b[31:0];
307				end
308				// The signed bit really only matters in the
309				// case of 64 bit multiply.  We'll keep track
310				// of it, though, and pretend in all other
311				// cases.
312				r_mpy_signed  <= i_op[0];
313	
314				if (i_stb)
315					r_hi  <= i_op[1];
316				else if (OPT_LOWPOWER)
317				begin
318					r_mpy_a_input <= 0;
319					r_mpy_b_input <= 0;
320					r_mpy_signed  <= 0;
321				end
322			end
323			// }}}
324	
325			assign	o_hi    = r_hi;
326			assign	o_busy  = |mpypipe[1:0];
327			assign	o_valid = mpypipe[2];
328	
329			// Second clock, do the multiplies, get the "partial products".
330			// {{{
331			// Here, we break our input up into two halves,
332			//
333			//   A  = (2^16 ah + al)
334			//   B  = (2^16 bh + bl)
335			//
336			// and use these to compute partial products.
337			//
338			//   AB = (2^32 ah*bh + 2^16 (ah*bl + al*bh) + (al*bl)
339			//
340			// Since we're following the FOIL algorithm to get here,
341			// we'll name these partial products according to FOIL.
342			//
343			// The trick is what happens if A or B is signed.  In
344			// those cases, the real value of A will not be given by
345			//	A = (2^16 ah + al)
346			// but rather
347			//	A = (2^16 ah[31^] + al) - 2^31
348			//  (where we have flipped the sign bit of A)
349			// and so ...
350			//
351			// AB= (2^16 ah + al - 2^31) * (2^16 bh + bl - 2^31)
352			//	= 2^32(ah*bh)
353			//		+2^16 (ah*bl+al*bh)
354			//		+(al*bl)
355			//		- 2^31 (2^16 bh+bl + 2^16 ah+al)
356			//		- 2^62
357			//	= 2^32(ah*bh)
358			//		+2^16 (ah*bl+al*bh)
359			//		+(al*bl)
360			//		- 2^31 (2^16 bh+bl + 2^16 ah+al + 2^31)
361			//
362			always @(posedge i_clk)
363			if (!OPT_LOWPOWER || mpypipe[0])
364			begin
365				pp_f<=r_mpy_a_input[31:16]*r_mpy_b_input[31:16];
366				pp_oi<=r_mpy_a_input[31:16]*r_mpy_b_input[15: 0]
367					+ r_mpy_a_input[15: 0]*r_mpy_b_input[31:16];
368				pp_l<=r_mpy_a_input[15: 0]*r_mpy_b_input[15: 0];
369				// And a special one for the sign
370				if (r_mpy_signed)
371					pp_s <= 32'h8000_0000-(
372					  	r_mpy_a_input[31:0]
373						+ r_mpy_b_input[31:0]);
374				else
375					pp_s <= 33'h0;
376			end
377			// }}}
378	
379			// Third clock, add the results and get a product: r_mpy_result
380			// {{{
381			always @(posedge i_clk)
382			if (!OPT_LOWPOWER || mpypipe[1])
383			begin
384				r_mpy_result[15:0] <= pp_l[15:0];
385				r_mpy_result[63:16] <=
386				  	{ 32'h00, pp_l[31:16] }
387					+ { 15'h00, pp_oi }
388					+ { pp_s, 15'h00 }
389					+ { pp_f, 16'h00 };
390			end
391			// }}}
392	
393			assign	o_result = r_mpy_result;
394			// Fourth clock -- results are clocked into writeback
395			// }}}
396		end else begin : MPYSLOW
397			// {{{
398			// Use an external multiply implementation, for when DSPs aren't
399			// available.
400			//
401	
402			// Declarations
403			// {{{
404			reg		r_hi;
405			// verilator coverage_off
406			// verilator lint_off UNUSED
407			wire		unused_aux;
408			wire	[65:0]	full_result;
409			// verilator lint_on  UNUSED
410			// verilator coverage_on
411			// }}}
412	
413			slowmpy #(.LGNA(6), .NA(33)
414			) slowmpyi(
415				i_clk, i_reset, i_stb,
416				{ (i_op[0])&(i_a[31]), i_a },
417				{ (i_op[0])&(i_b[31]), i_b }, 1'b0, o_busy,
418					o_valid, full_result, unused_aux
419			);
420	
421			assign	o_result = full_result[63:0];
422	
423			always @(posedge i_clk)
424			if (i_stb)
425				r_hi  <= i_op[1];
426	
427			assign	o_hi = r_hi;
428			// }}}
429		end end end end end
430		endgenerate // All possible multiply results have been determined
431	
432	endmodule
433

