1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/slowmpy.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is a signed (OPT_SIGNED=1) or unsigned (OPT_SIGNED=0)
8	// 		multiply designed for low logic and slow data signals.  It
9	// 	takes one clock per bit plus two more to complete the multiply.
10	//
11	//	The OPT_SIGNED version of this algorithm was found on Wikipedia at
12	//	https://en.wikipedia.org/wiki/Binary_multiplier.
13	//
14	// Creator:	Dan Gisselquist, Ph.D.
15	//		Gisselquist Technology, LLC
16	//
17	////////////////////////////////////////////////////////////////////////////////
18	// }}}
19	// Copyright (C) 2018-2025, Gisselquist Technology, LLC
20	// {{{
21	// This program is free software (firmware): you can redistribute it and/or
22	// modify it under the terms of the GNU General Public License as published
23	// by the Free Software Foundation, either version 3 of the License, or (at
24	// your option) any later version.
25	//
26	// This program is distributed in the hope that it will be useful, but WITHOUT
27	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
28	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
29	// for more details.
30	//
31	// You should have received a copy of the GNU General Public License along
32	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
33	// target there if the PDF file isn't present.)  If not, see
34	// <http://www.gnu.org/licenses/> for a copy.
35	// }}}
36	// License:	GPL, v3, as defined and found on www.gnu.org,
37	// {{{
38	//		http://www.gnu.org/licenses/gpl.html
39	//
40	////////////////////////////////////////////////////////////////////////////////
41	//
42	`default_nettype	none
43	// }}}
44	module	slowmpy #(
45			// {{{
46			parameter			LGNA = 6,
47			parameter	[LGNA:0]	NA = 33,
48			parameter	[0:0]		OPT_SIGNED = 1'b1,
49			parameter	[0:0]		OPT_LOWPOWER = 1'b0,
50			localparam	NB = NA // Must be = NA for OPT_SIGNED to work
51			// }}}
52		) (
53			// {{{
54			input	wire				i_clk, i_reset,
55			//
56			input	wire				i_stb,
57			input	wire	signed	[(NA-1):0]	i_a,
58			input	wire	signed	[(NB-1):0]	i_b,
59			// verilator coverage_off
60			input	wire				i_aux,
61			// verilator coverage_on
62			output	reg				o_busy, o_done,
63			output	reg	signed	[(NA+NB-1):0]	o_p,
64			// verilator coverage_off
65			output	reg				o_aux
66			// verilator coverage_on
67			// }}}
68		);
69	
70		// Declarations
71		// {{{
72		reg	[LGNA-1:0]	count;
73		reg	[NA-1:0]	p_a;
74		reg	[NB-1:0]	p_b;
75		reg	[NA+NB-1:0]	partial;
76		// verilator coverage_off
77		reg			aux;
78		// verilator coverage_on
79		reg			almost_done;
80		wire			pre_done;
81		wire	[NA-1:0]	pwire;
82		// }}}
83	
84		assign	pre_done = (count == 0);
85	
86		// almost_done
87		// {{{
88		initial	almost_done = 1'b0;
89		always @(posedge i_clk)
90			almost_done <= (!i_reset)&&(o_busy)&&(pre_done);
91		// }}}
92	
93		// aux, o_done, o_busy
94		// {{{
95		initial	aux    = 0;
96		initial	o_done = 0;
97		initial	o_busy = 0;
98		always @(posedge i_clk)
99		if (i_reset)
100		begin
101			// {{{
102			aux    <= 0;
103			o_done <= 0;
104			o_busy <= 0;
105			// }}}
106		end else if (!o_busy)
107		begin
108			// {{{
109			o_done <= 0;
110			o_busy <= i_stb;
111			aux    <= (!OPT_LOWPOWER || i_stb) ? i_aux : 0;
112			// }}}
113		end else if (almost_done)
114		begin
115			// {{{
116			o_done <= 1;
117			o_busy <= 0;
118			// }}}
119		end else
120			o_done <= 0;
121		// }}}
122	
123		assign	pwire = (p_b[0] ? p_a : 0);
124	
125		// count, partial, p_a, p_b
126		// {{{
127		always @(posedge i_clk)
128		if (!o_busy)
129		begin
130			count <= NA[LGNA-1:0]-1;
131			partial <= 0;
132			p_a <= i_a;
133			p_b <= i_b;
134	
135			if (OPT_LOWPOWER && !i_stb)
136			begin
137				p_a <= 0;
138				p_b <= 0;
139			end
140		end else begin
141			p_b <= (p_b >> 1);
142			// partial[NA+NB-1:NB] <= partial[NA+NB
143			partial[NB-2:0] <= partial[NB-1:1];
144			if ((OPT_SIGNED)&&(pre_done))
145				partial[NA+NB-1:NB-1] <= { 1'b0, partial[NA+NB-1:NB]} +
146					{ 1'b0, pwire[NA-1], ~pwire[NA-2:0] };
147			else if (OPT_SIGNED)
148				partial[NA+NB-1:NB-1] <= {1'b0,partial[NA+NB-1:NB]} +
149					{ 1'b0, !pwire[NA-1], pwire[NA-2:0] };
150			else
151				partial[NA+NB-1:NB-1] <= {1'b0, partial[NA+NB-1:NB]}
152					+ ((p_b[0]) ? {1'b0,p_a} : 0);
153			count <= count - 1;
154		end
155		// }}}
156	
157		// o_p, o_aux
158		// {{{
159		always @(posedge i_clk)
160		if (almost_done)
161		begin
162			if (OPT_SIGNED)
163				o_p   <= partial[NA+NB-1:0]
164					+ { 1'b1, {(NA-2){1'b0}}, 1'b1, {(NB){1'b0}} };
165			else
166				o_p   <= partial[NA+NB-1:0];
167			o_aux <= aux;
168		end
169		// }}}
170	////////////////////////////////////////////////////////////////////////////////
171	////////////////////////////////////////////////////////////////////////////////
172	////////////////////////////////////////////////////////////////////////////////
173	//
174	// Formal properties
175	// {{{
176	////////////////////////////////////////////////////////////////////////////////
177	////////////////////////////////////////////////////////////////////////////////
178	////////////////////////////////////////////////////////////////////////////////
179	`ifdef	FORMAL
180		// Declarations and reset
181		// {{{
182	`define	ASSERT	assert
183	`ifdef	SLOWMPY
184	`define	ASSUME	assume
185	`else
186	`define	ASSUME	assert
187	`endif
188	
189		reg	f_past_valid;
190	
191		initial	f_past_valid = 1'b0;
192		always @(posedge i_clk)
193			f_past_valid <= 1'b1;
194	
195		initial	assume(i_reset);
196		always @(*)
197		if (!f_past_valid)
198			`ASSUME(i_reset);
199		// }}}
200	
201		always @(posedge i_clk)
202		if ((!f_past_valid)||($past(i_reset)))
203		begin
204			`ASSERT(almost_done == 0);
205			`ASSERT(o_done == 0);
206			`ASSERT(o_busy == 0);
207			`ASSERT(aux == 0);
208		end
209	
210		// Assumptions about our inputs
211		always @(posedge i_clk)
212		if ((f_past_valid)&&(!$past(i_reset))&&($past(i_stb))&&($past(o_busy)))
213		begin
214			`ASSUME(i_stb);
215			`ASSUME($stable(i_a));
216			`ASSUME($stable(i_b));
217		end
218	
219		//
220		// For now, just formally verify our internal signaling
221		// {{{
222	
223		always @(posedge i_clk)
224			`ASSERT(almost_done == (o_busy&&(&count)));
225	
226		always @(*)
227			if (!(&count[LGNA-1:1])||(count[0]))
228				`ASSERT(!o_done);
229	
230		always @(posedge i_clk)
231		if (o_done)
232			`ASSERT(!o_busy);
233		always @(posedge i_clk)
234		if (!o_busy)
235			`ASSERT(!almost_done);
236	
237		reg	[NA-1:0]	f_a, f_b;
238		always @(posedge i_clk)
239		if ((i_stb)&&(!o_busy))
240		begin
241			f_a <= i_a;
242			f_b <= i_b;
243		end
244	
245		always @(*)
246		if (o_done)
247		begin
248			if ((f_a == 0)||(f_b == 0))
249			begin
250				`ASSERT(o_p == 0);
251			end else
252				`ASSERT(o_p[NA+NB-1] == f_a[NA-1] ^ f_b[NA-1]);
253		end
254		// }}}
255		////////////////////////////////////////////////////////////////////////
256		//
257		// Cover properties
258		// {{{
259		////////////////////////////////////////////////////////////////////////
260		//
261		always @(posedge i_clk)
262			cover(o_done);
263	
264		reg	cvr_past_done;
265		initial	cvr_past_done = 1'b0;
266		always @(posedge i_clk)
267		if (o_done)
268			cvr_past_done <= 1'b1;
269	
270		always @(posedge i_clk)
271			cover((o_done)&&(cvr_past_done));
272		// }}}
273	`endif
274	// }}}
275	endmodule
276

