	//   valid yet until then.
	if (OPT_PIPELINED || !op_valid)
	begin
		op_valid     <= (w_op_valid)||(dcd_early_branch);
		op_valid_alu <= (w_op_valid)&&((dcd_ALU)||(dcd_illegal));
		op_valid_mem <= (dcd_M)&&(!dcd_illegal)
